onClick:
{{
  (async function() {
    try {
      // 1. On lance la demande
      await Demander_Facture.run();
      closeModal('Modal_generer_facture');
      showAlert('Génération de la facture lancée...', 'info');

      let tentatives = 0;
      const maxTentatives = 30;

      const interval = setInterval(async () => {
        tentatives++;

        // 2. On rafraîchit les données pour vérifier le statut
        const res = await Get_Commande_ById.run();
        const blData = res[0] || Get_Commande_ById.data[0];

        // 3. Dès que n8n a passé le statut à "Facturé"
        if (blData && blData.Statut_Facturation === 'Facturé') {
          clearInterval(interval);
          showAlert('Facture générée avec succès !', 'success');

          // 4. On redirige vers la vue facture avec l'ID_BL actuel
          navigateTo('Détail Facture', { id: blData.ID_BL });
        } 
        else if (tentatives >= maxTentatives) {
          clearInterval(interval);
          showAlert('La génération prend plus de temps que prévu...', 'warning');
        }
      }, 1000);

    } catch (err) {
      showAlert('Erreur lors du lancement de la facturation', 'error');
      console.error(err);
    }
  })()
}}
